<?php
/**
 * Plugin Name: NESPORTS3 Updater V65 (Official Elementor get_builder_content_for_display Engine)
 * Description: Directly calls get_builder_content_for_display() to render saved Elementor builder HTML on all live pages without query conflicts.
 * Version: 65.0
 * Author: NESports
 */

if (!defined('ABSPATH')) exit;

function run_nesports_v65_sync() {
    $target_dirs = array(
        WP_PLUGIN_DIR . '/nesports-pro',
        WP_PLUGIN_DIR . '/nesports-pro-store',
        WP_PLUGIN_DIR . '/nesports-custom'
    );
    if (is_dir(WP_PLUGIN_DIR)) {
        $files = scandir(WP_PLUGIN_DIR);
        foreach ($files as $f) {
            if ($f === '.' || $f === '..') continue;
            if (stripos($f, 'nesport') !== false) {
                $full = WP_PLUGIN_DIR . '/' . $f;
                if (is_dir($full) && !in_array($full, $target_dirs)) {
                    $target_dirs[] = $full;
                }
            }
        }
    }

    $payloads = array(
        'templates/page-story.php' => base64_decode(''),
        'templates/page-home.php' => base64_decode(''),
        'templates/page-contact.php' => base64_decode(''),
        'includes/class-nesports-frontend.php' => base64_decode(''),
        'includes/class-nesports-admin.php' => base64_decode(''),
        'includes/class-nesports-elementor.php' => base64_decode(''),
        'includes/elementor-widgets/widget-story.php' => base64_decode(''),
        'assets/js/nesports-frontend.js' => base64_decode(''),

    );

    $results = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $results[$td] = array();
        foreach ($payloads as $rel => $data) {
            $dest = $td . '/' . $rel;
            $d = dirname($dest);
            if (!is_dir($d)) {
                if (function_exists('wp_mkdir_p')) {
                    wp_mkdir_p($d);
                } else {
                    @mkdir($d, 0755, true);
                }
            }
            $w = file_put_contents($dest, $data);
            $results[$td][$rel] = ($w !== false) ? "SUCCESS ($w bytes)" : "ERROR";
        }
    }

    // 1. Explicitly enable Elementor Builder mode on all core pages
    $target_posts = array(30090, 4400, 1038);
    foreach ($target_posts as $pid) {
        update_post_meta($pid, '_nesports_elementor_seeded', '1');
        update_post_meta($pid, '_elementor_edit_mode', 'builder');
        clean_post_cache($pid);
    }

    // 2. Clear Elementor cache & flush
    if (class_exists('\Elementor\Plugin')) {
        \Elementor\Plugin::$instance->files_manager->clear_cache();
    }

    // 3. Deactivate old updaters
    $active = get_option('active_plugins', array());
    if (is_array($active)) {
        $clean_active = array();
        foreach ($active as $p) {
            if (stripos($p, 'updater-v') !== false || stripos($p, 'nesports-patch') !== false) {
                continue;
            }
            $clean_active[] = $p;
        }
        update_option('active_plugins', $clean_active);
    }

    return $results;
}

add_action('init', function() {
    if (isset($_GET['nesports_apply_v65']) && $_GET['nesports_apply_v65'] === '1') {
        $res = run_nesports_v65_sync();
        header('Content-Type: application/json');
        echo json_encode(array('status' => 'ok', 'results' => $res));
        exit;
    }
    run_nesports_v65_sync();
}, 1);

register_activation_hook(__FILE__, 'run_nesports_v65_sync');
